export const RELEASES=[{version:'1.14.1',date:'3 Kasım 2026',title:'AgarV gözlemine göre Gold harcama efekti',items:['Gold harcamaları bakiyenin üstünde sarı eksi tutarlar olarak ayrı ayrı yükselir. Tek seferlik tutarın yanında Gold etiketi gösterilmez.','Aynı ağ paketinde gelen A/S harcamaları birleştirilmez; başarısız veya tekrarlanan durum paketleri yeni harcama yazısı oluşturmaz.','AgarV’de diken çarpışmasında 25 parçaya açılma gözlendi. Kesin skor eşiği, yem sayısı ve fırlatma mesafesi 1 FPS görüntüyle doğrulanamadığı için mevcut fizik değerleri korundu.']},{"version": "1.14.0", "date": "3 Kasım 2026", "title": "Rekortmen tacı ve Sayfam rekorları", "items": ["Güncel oda rekorunun sahibi o odada oynarken tüm hücrelerinin üstünde altın taç görünür. İsim taklidi taç kazandırmaz; rekor satılınca veya aktarılınca yeni sahibi taç alır.", "Sayfam’da sahip olunan bütün güncel oda rekorları ayrı ayrı gösterilir. Eski ve eşit skorlu kayıtlar başka bir hesaba rekor sahipliği vermez.", "Galibiyetler referans görseldeki gibi geniş, skora göre renklenen çubuklar hâlinde düzenlendi; skor ve tarih üzerine gelince veya dokununca gösterilir.", "AgarV’de 1 FPS görüntü sınırı nedeniyle dikenin kaç yemle ve ne kadar uzağa atıldığı güvenilir ölçülemedi; doğrulanmamış fizik değerleri değiştirilmedi."]},{"version": "1.13.0", "date": "3 Kasım 2026", "title": "Zirve Yolu, MMA ödülleri ve rekor görünümü", "items": ["Oda ve sürenin altında yalnızca rekor sahibinin adı, büyük sarı yazıyla görünür. Skorlu genel rekor duyurusu bütün odalarda 60 dakika kalır; sonraki rekor süreyi yeniden başlatır.", "Harcanan Gold, bakiyenin hemen üstünde eksi işaretiyle gösterilir. Dil seçiminde yalnızca bayraklar kalır.", "MMA ödülü aktif oyuncu sayısına göre belirlenir: 1–4 kişi 50.000, 5–9 kişi 100.000, 10–14 kişi 150.000, 15–19 kişi 200.000, 20 ve üzeri 250.000 Gold. Ödül normal Gold bakiyesine yatırılır.", "Sayfam’a kaydırma çubuğu eklendi. Galibiyetler küçük oda kutuları ve skora göre genişleyen renkli çubuklarla gösterilir.", "Zirve Yolu: Avcı, Şampiyon veya Klan yolunu seç; 20 kademede ilerle. Her beş kademede üç ödülden birini seç, son kademede sezon numaralı kalıcı unvan kazan. Sezon bileti 5.000.000 Gold’dur."]},{"version": "1.12.0", "date": "2 Kasım 2026", "title": "Aylık sezon, süreli rekor duyurusu ve oda ayarları", "items": ["Galeriden alınan skinlerin görünen adları ve seçim kodları Agarm olarak değiştirildi. Önceki skin kodları çalışmaya devam eder.", "Yalnızca harita bitiş çizgisi koyu kırmızı; iç çizgiler yeniden ince gri. Sistem yazıları kırmızı.", "Odalar bölümünde Gold harcamasının ödüle eklenmesi Açık/Kapalı seçilir. Başlangıçta kapalıdır; ücretsiz MMA Gold’u ödüle eklenmez.", "Yönetici panelinden oda tur süresi ayarlanır. Kaydedilen odanın sayacı yeniden başlar ve sonraki turlar aynı sürede oynanır.", "Yeni rekor bütün odalarda 60 dakika yeşil gösterilir. Sonraki rekor duyuruyu değiştirir ve süreyi yeniden başlatır; normal tur sonucu süreyi uzatmaz.", "Oda rekor sahibinin yanında REKOR etiketi kaldırıldı.", "Sezonlar 30 gün sürer ve menüde geri sayım vardır. Sezon sıralaması o sezondaki galibiyetlere göre yapılır.", "Tamamlanmış sezonun en çok galibiyet alan oyuncusu odaya girince sezon numarasıyla 12 saniyelik kırmızı giriş bildirimi görünür."]},{"version": "1.11.0", "date": "2 Kasım 2026", "title": "MMA süreleri, rekor işlemleri ve oyun kontrolleri", "items": ["Üç MMA odası 15 dakika sürer; bitişler 5 dakika arayla gelir. MMA-2 ve MMA-3 haritaları daha büyüktür.", "X veya Z basılıyken sekme değiştirildiğinde Gold devam eder; aynı tuşa tekrar basınca durur.", "Diken görseli büyütüldü, harita çizgileri koyu kırmızı oldu. Hücreler kenarda yarıya kadar dışarı çıkabilir.", "Küçük haritada takım arkadaşları sarı, klan arkadaşları turkuaz görünür. Bot sayacı kaldırıldı; oda başına aynı IP en fazla 5 hesapla sınırlıdır.", "Sayfam’dan güncel rekorun ismi 100.000 Gold’a değiştirilir veya rekor başka hesaba 100.000 Gold’a aktarılır. Satış fiyatını sahibi belirler; yalnızca klan başkanları satın alabilir.", "Güncel oda rekoru sürenin altında sarı; yönetici duyurusu bütün odalarda yeşil gösterilir. Dil düğmeleri ülke bayraklarıyla yenilendi.", "AgarV ile saniyelik skor azalmasının ve diken ödülünün birebir eşleşmesi henüz doğrulanmadı."]},{"version": "1.10.0", "date": "2 Kasım 2026", "title": "Üç MMA odası ve kişiye özel kayıtlı skinler", "items": ["MMA-1, MMA-2 ve MMA-3 açık. Parça sınırları sırasıyla 220.000, 250.000 ve 350.000 skor; en fazla 25 parça.", "Her MMA odasının 80 milyonluk kişisel Gold bakiyesi ayrıdır; 5 saatte yenilenir. Normal Gold ve Bonus’a aktarılmaz.", "İnternetten alınan 29 skin Agarm adlarıyla galeriye eklendi. Galeride 59 internet görseli var; yapay zekâ skinleri kaldırıldı.", "Skin Galerisi yeni sekmede açılır. Kaydırmak yerine Önceki / Sonraki düğmeleriyle sayfa değiştir; seçtiğin skin oyun sekmesine aktarılır.", "Her başarılı özel skin yüklemesi 10.000 Gold’dur. Skin Kayıtlı Skinler bölümünde kalır; onaylandıktan sonra yalnızca yükleyen hesap kullanabilir."]},{"version": "1.9.2", "date": "2 Kasım 2026", "title": "Dil seçimi ve mobil oyuncu göstergesi", "items": ["Türkçe, İngilizce, İspanyolca, Almanca ve Rusça düğmeleri menü ve oyun arayüzünün dilini değiştirir. Seçim bu tarayıcıda hatırlanır.", "Mobil Kontroller seçeneği menüden kaldırıldı. Dokunmatik kontroller uygun cihazlarda otomatik açılır; mobil oyuncunun sıralamasında küçük telefon simgesi görünür.", "Doğal yem 10 skor verir. Diken ödülü ve bölünme fiziği için AgarV ile birebir eşleşme henüz doğrulanmadı."]},{"version": "1.9.1", "date": "2 Kasım 2026", "title": "Gerçek fotoğraflarla genişleyen ücretsiz skin galerisi", "items": ["Galeri 34 skine çıktı. Beşiktaş, Galatasaray ve Fenerbahçe formalı futbolcu fotoğrafları eklendi.", "Kadın moda, erkek portre ve fitness fotoğrafları ücretsiz seçilebilir.", "Görseller oyuna uygun WebP boyutuna getirildi. Mevcut skin kodları korundu; özel yükleme ücreti 10.000 Gold ve sınırı 2 MB."]},{version:'1.9.0',date:'2 Kasım 2026',title:'Panel yetkileri ve yeni ücretsiz skin galerisi',items:['Hesap sahibi hesap no veya e-posta ile seçtiği panel yetkilerini verir ve geri alır. Her işlem sunucuda ayrı yetki kontrolünden geçer.','Eski emoji skinler yerine yeni karakter görselleri geldi. Galeri skinleri ücretsiz, özel görsel yükleme 10.000 Gold oldu.','A tuşu 10 Gold karşılığında 50 skor verir; S tuşu 100 Gold karşılığında 250 skor vermeye devam eder.','Gold harcaması hücrenin yanında eksi işaretiyle gösterilir. Dikenler ana dikenden çıkarak fırlar; 25 parçadayken diken yiyerek skor toplanabilir.']},{version:'1.8.0',date:'2 Kasım 2026',title:'Sohbet ücretleri, takım renkleri ve oyuncu takibi',items:['Haykır tüm odalara 50.000 Gold karşılığında mavi mesaj gönderir. Yetersiz bakiyede mesaj gönderilmez.','Klan sohbetini yalnızca aynı odadaki klan üyeleri görür. Takım sarı, klan turkuaz; ikisinde de olanlarda takım önceliklidir.','Sıralamada kendi ismin kırmızı, takım sarı, klan turkuaz ve diğerleri beyazdır. Hücre isim ve skorları da ilişki rengine uyar.','Kamera oyuncuyu takip eder; yön kilidi yalnızca küçük noktayla gösterilir. Harcanan Gold eksi işaretiyle görünür.','Yemle çoğalan diken, yem yönünde fırlatılır; hareketi yumuşatılır. 80 taban ve 800 toplam diken sınırı korunur.']},{version:'1.7.0',date:'2 Kasım 2026',title:'Mobil sohbet, MMA-1 ve oyun dengesi',items:['Mobil sohbet küçük simgeyle açılır; menü taşmaları ve GM paneli kaydırması düzeltildi.','MMA-1: hesaba özel 80 milyon oda Gold’u, her 5 saatte yeniden dolar ve diğer odalara taşınmaz.','Hücre hareketi yavaşlatıldı; doğal ve atılan yemler 10 skor verir.','Başlangıçta 80 diken vardır. Yedi yemle boş alana yeni diken çıkar; oda sınırı 800’dür.','Fare tekerleğiyle yakınlaştırma Etrafı Göster açıkken de çalışır; masaüstü menü düğmesi gizlendi.']},{version:'1.6.0',date:'2 Kasım 2026',title:'Oda geçişi, tema ve sohbet düzeltmeleri',items:['Oyundayken farklı odayı seçip Oyna veya İzle ile geçebilirsin. Aynı odada mevcut hücren korunur.','Tekrar yalnızca yutulduktan sonra ve düğmeye basıldığında açılır.','Karanlık, Kenar, Klan ve Etrafı Göster ayarları düzeltildi; kesik hücre halkası kaldırıldı.','Sohbet Haykır, Klan, Takım ve Herkes kanallarına ayrıldı.','Skin yükleme sınırı 2 MB oldu. ZirvePass kapalı: Yakında gelecek.']},{version:'1.5.0',date:'1 Kasım 2026',title:'Sayfam, menü ve GM paneli yenilendi',items:['Ana menü üç sütun, neon oyun çerçevesi ve kompakt kontrollerle yeniden düzenlendi.','Sayfam açık mavi zemine, ortalanmış hesap işlemlerine ve skora göre genişleyen galibiyet kutularına geçti.','GM paneli sol menü, genel bakış, canlı oyuncular, kullanıcılar, odalar, Boost ve ekonomi sayfalarına ayrıldı.','Canlı oyuncu satırından skor ekleme, sohbet yasağı ve oyuncu atma yapılabilir.']},{version:'1.4.0',date:'1 Kasım 2026',title:'Daha kompakt menü ve yeni oda sırası',items:['Masaüstü menüsü ekran yüksekliğine uyarlanır; daha küçük kartlar ve kontroller.','Pin Sorgula menüden kaldırıldı. SPVS-1 ilk sıraya alındı, Boss odası kaldırıldı.','FFA-10’dan sonra Etkinlik-1, Alan-1 ve yeni Alan-2 sıralanır.','Oyun ekranında skor, Gold, sonuç duyuruları ve sağ alt bilgiler yeniden yerleştirildi.']},{version:'1.3.0',date:'1 Kasım 2026',title:'Rekorların son 5 dakikasını izle',items:['Tekrarlar ayrı sekmede açılır; duraklatma, sarma ve hız seçimi vardır.','Onur Tablosu rekor sahibinin turda kullandığı skini gösterir.','Sayfam kupa kartı, Gold/Bonus satırları ve renkli galibiyet kutularıyla yenilendi.','ZirvePass fiyatı 5.000.000 Gold oldu.']}];
export function releaseNews({esc}){const r=RELEASES[0];return `<b>${esc(r.title)}</b><p>Sürüm ${esc(r.version)} · ${esc(r.date)}</p><ul>${r.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><button data-page="updates">Tüm güncelleme notları →</button>`}
export function releaseHistory({esc}){return `<div class="doc"><h2>Son Güncellemeler</h2>${RELEASES.map(r=>`<section class="sub-card"><small>${esc(r.date)} · ${esc(r.version)}</small><h3>${esc(r.title)}</h3><ul>${r.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`).join('')}</div>`}
